def _deep_copy(value):
    """Return a copy of *value* sharing no mutable containers with it."""
    if isinstance(value, dict):
        return {k: _deep_copy(v) for k, v in value.items()}
    if isinstance(value, list):
        return [_deep_copy(item) for item in value]
    return value


def _merge_dicts(base, override):
    """Merge the two dicts and return a brand-new result dict."""
    result = {k: _deep_copy(v) for k, v in base.items()}
    for key, value in override.items():
        if value is None:
            # Removal: applies even when the key is absent from base.
            result.pop(key, None)
            continue
        if isinstance(value, dict) and isinstance(base.get(key), dict):
            result[key] = _merge_dicts(base[key], value)
        elif isinstance(value, dict):
            result[key] = _deep_copy(value)
        else:
            # Lists and scalars are replaced, never concatenated.
            result[key] = _deep_copy(value)
    return result


def merge(base: dict, override: dict) -> dict:
    """Deep-merge *override* into *base* and return the result as a new dict.

    Rules:
      - Nested dicts are merged recursively.
      - Lists and scalars from *override* replace the base value.
      - A key whose override value is ``None`` is removed from the result
        (a no-op when the key is absent from base).
      - Neither input is mutated, and no mutable object in the result is
        shared with either input.

    Raises:
        ValueError: if either argument is not a ``dict``.
    """
    if not isinstance(base, dict):
        raise ValueError("base must be a dict")
    if not isinstance(override, dict):
        raise ValueError("override must be a dict")
    return _merge_dicts(base, override)


if __name__ == "__main__":
    assert merge({"a": {"b": 1, "c": 2}}, {"a": {"c": 3}}) == {"a": {"b": 1, "c": 3}}
    assert merge({"a": 1}, {"a": None}) == {}
    base = {"a": [1, 2], "b": {"x": 1}, "c": "keep", "d": [1]}
    override = {"a": [3], "b": {"y": 2}, "c": None, "d": None}
    result = merge(base, override)
    assert result == {"a": [3], "b": {"x": 1, "y": 2}}
    assert base == {"a": [1, 2], "b": {"x": 1}, "c": "keep", "d": [1]}
    assert override == {"a": [3], "b": {"y": 2}, "c": None, "d": None}
    assert result["a"] is not base["a"] and result["a"] is not override["a"]
    assert result["b"] is not base["b"] and result["b"] is not override["b"]
    try:
